   morph.css's collapsed↔expanded interp (retargeted onto `.dock-plate`) source-order-wins.
   Splits `.glass-dock`'s triple identity (surface + clip aperture + item container) — the
   dock-disease terminal cure. */
@import "./styles/dock.css";
@import "./styles/morph.css";
@import "./legibility/adaptive-legibility.css";
@import "./styles/density.css";
@import "./styles/shape.css";
@import "./layers/layers.css";
@import "./layers/layer-group.css";
